let data,world=[],tab='home',modelReady=false,pendingQuestion='';const names={home:'首页',monitor:'行业动态监测',dashboard:'全球态势总览',events:'行业动态监测',research:'量化分析工作台',analysis:'行业数据洞察',graph:'产业关联图谱',library:'情报证据中心',sources:'全球信息感知'};
