function seriesPanel(){return (data.series||[]).filter(s=>s.frequency==='月度').map(s=>{const rows=s.rows.slice(-18);if(!rows.length)return '<div class="notice">所选期间没有该指标的官方观察值。</div>';const min=Math.floor(Math.min(...rows.map(r=>r.value))*.9),max=Math.ceil(Math.max(...rows.map(r=>r.value))*1.05),pts=rows.map((r,i)=>({...r,x:50+i*680/Math.max(1,rows.length-1),y:155-(r.value-min)/(max-min)*120}));return panel('海上原油产量 · 官方月度序列','REAL DATA / EIA',`<p class="meta">${esc(s.name)} · ${esc(s.unit)} · 最近${rows.length}期（纵轴非零起点）</p><svg class="line-chart" viewBox="0 0 780 190"><text x="5" y="30">${max}</text><text x="5" y="155">${min}</text><path d="M50 155H740" style="stroke:var(--line)"/><path d="${pts.map((p,i)=>(i?'L':'M')+p.x+','+p.y).join(' ')}"/>${pts.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="4"><title>${p.period}：${p.value} ${s.unit}</title></circle>${i%3===0||i===pts.length-1?`<text x="${p.x}" y="180" text-anchor="middle">${p.period}</text>`:''}`).join('')}</svg><p class="map-note">${esc(s.note)} 本次读取：${formatDisplayDate(s.checkedAt)}。新闻量和产量分别统计。</p><details><summary>查看全部数值与原始表格 ↗</summary><a href="${esc(s.sourceUrl)}" target="_blank" rel="noopener noreferrer">EIA 原始月度表格 ↗</a><div class="table-wrap"><table><thead><tr><th>统计期</th><th>原始值</th><th>单位</th></tr></thead><tbody>${s.rows.map(r=>`<tr><td>${r.period}</td><td>${r.original}</td><td>${esc(s.unit)}</td></tr>`).join('')}</tbody></table></div></details>`);}).join('');}
