function filters(){return{sourceId:$('#source').value,topic:$('#topic').value,country:$('#country').value,from:$('#from').value,to:$('#to').value};}
const readCache=new Map(),pendingReads=new Map();let cacheEpoch=0;
async function api(p,body){
 const cachedRead=!body&&/^(data|options)\?|^(source-funnels|sensing-summary)$/.test(p),cached=readCache.get(p);
 if(cachedRead&&cached&&Date.now()-cached.at<60000)return cached.value;
 if(cachedRead&&pendingReads.has(p))return pendingReads.get(p);
 if(body){cacheEpoch++;readCache.clear();pendingReads.clear();}
 const epoch=cacheEpoch;
 const task=(async()=>{const r=await fetch('api/'+p,{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const d=await r.json();if(r.status===401){readCache.clear();$('#login').hidden=false;}if(!r.ok)throw Object.assign(new Error(d.message||d.error||'请求失败'),{fieldErrors:d.fieldErrors||[]});if(cachedRead&&epoch===cacheEpoch){if(readCache.size>=12)readCache.delete(readCache.keys().next().value);readCache.set(p,{at:Date.now(),value:d});}return d;})();
 if(cachedRead)pendingReads.set(p,task);
 try{return await task;}finally{if(pendingReads.get(p)===task)pendingReads.delete(p);}
}
function queryFor(scope){return new URLSearchParams(Object.entries(scope).filter(([,value])=>value)).toString();}
let routeState=parseRoute(location.hash),navigationState=readNavigation(sessionStorage);
function activeTab(){return parseRoute(location.hash).module;}
function saveCurrentNavigation(writeUrl=true){
 if(routeState.module==='home')return;
 navigationState.shared=filters();navigationState.local[routeState.module]={pages:{...pages},libraryQuery,scrollY};
 navigationState.lastResearch=routeHash(routeState,filters());saveNavigation(sessionStorage,navigationState);
 if(writeUrl)window.history.replaceState(null,'',navigationState.lastResearch);
}
function restoreNavigation(){
 routeState=parseRoute(location.hash);const scope=sharedScope(routeState,{});
 if(scope.country&&world.length&&!world.some(c=>c.code===scope.country)){scope.country='';routeState.error='国家代码不在当前地图字典中，请重新选择';}
 for(const [id,key]of [['topic','topic'],['country','country'],['source','sourceId'],['from','from'],['to','to']]){const control=$('#'+id),value=scope[key];if(control.tagName==='SELECT'&&value&&![...control.options].some(o=>o.value===value))control.add(new Option(value,value));control.value=value;}
 for(const key of Object.keys(pages))pages[key]=1;libraryQuery='';
 window.history.replaceState(null,'',routeHash(routeState,routeState.module==='home'?{}:scope));
}
