function monitor(){const view=parseRoute(location.hash).view||'objects';const scope=filters();return `<section class="panel monitor-header"><small>INDUSTRY MONITOR / EVIDENCE FIRST</small><h1>行业动态监测</h1><p class="meta">按对象查看原始资料、关系线索与历史变化，区分实际事件和系统处理记录。</p><div class="monitor-tabs">${[['objects','对象档案'],['relations','关系视图'],['events','事件明细']].map(([key,name])=>`<a class="${view===key?'primary':''}" href="${esc(routeHash({module:'monitor',view:key},scope))}">${name}</a>`).join('')}</div></section><section class="panel" id="monitor-flow"></section><section class="panel" id="monitor-tools"><small>F02 / 一级筛选工具区</small><div id="monitor-filter-slot"></div></section><section class="panel" id="monitor-summary"></section>`+(view==='objects'?'<section class="panel" id="object-host"></section>':view==='relations'?graph():panel('事件与报道线索','EVENTS / ORIGINAL EVIDENCE',pageList(data.events.slice().sort((a,b)=>(b.publishedAt||'').localeCompare(a.publishedAt||'')),'events',e=>eventCard(e))||'<p class="empty">当前范围暂无事件</p>'));}
let countryDispose=()=>{};
let countryMapData=null;
function setupCountryDossier(){
 const content=$('#content'),layout=content.querySelector('.dashboard-map-row');if(!layout)return;
 const mapPanel=layout.firstElementChild,toolbar=document.createElement('section');toolbar.className='panel';toolbar.id='country-toolbar';content.prepend(toolbar,mapPanel);
 const head=mapPanel.querySelector('.panel-head'),canvas=document.createElement('div');canvas.id='country-map-scope';const mapNotice=document.createElement('p');mapNotice.setAttribute('role','status');mapPanel.replaceChildren(head,mapNotice,canvas);
 const host=document.createElement('section');host.className='panel';host.id='country-dossier';mapPanel.after(host);
 const signals=content.querySelector('#change-signals')?.closest('.panel');if(signals)host.after(signals);
 const legacy=document.createElement('details');legacy.className='panel';legacy.innerHTML='<summary>展开原有报道与趋势（旧版快照，独立范围）</summary>';content.append(legacy);for(const child of [...content.children])if(![toolbar,mapPanel,host,signals,legacy].includes(child))legacy.append(child);
 // The current country view has its own versioned data; fetch the legacy snapshot only on expansion.
 if(['summary','signals'].includes(data.projection)){
  legacy.querySelectorAll(':scope > :not(summary)').forEach(child=>child.remove());
  const pending=document.createElement('p');pending.textContent='展开后读取原有报道与趋势。';legacy.append(pending);
  let loading=false,loaded=false;const legacyQuery=queryFor(filters());
  legacy.addEventListener('toggle',async()=>{if(!legacy.open||loading||loaded)return;loading=true;pending.textContent='正在读取原有报道与趋势…';try{
   const full=await api('data?'+legacyQuery+(legacyQuery?'&':'')+'projection=full');if(!legacy.isConnected)return;
   data=full;const holder=document.createElement('div');holder.innerHTML=dashboard();holder.querySelector('.dashboard-map-row')?.firstElementChild?.remove();holder.querySelector('#change-signals')?.closest('.panel')?.remove();pending.remove();legacy.append(...holder.children);loaded=true;setupEnhancements(full,openDoc);setupCharts();setupDashboardCharts();
  }catch(error){if(legacy.isConnected)pending.textContent='旧版资料读取失败，请收起后重新展开：'+error.message;}finally{loading=false;}});
 }
 const dictionary=world.filter(c=>/^[A-Z]{2}$/.test(c.code)).map(c=>({...c,name:data.countryOptions.find(x=>x.code===c.code)?.name||c.name}));
 countryDispose=mountCountryDossier(host,{toolbar,dictionary,onLoading:({loading,error})=>{canvas.hidden=loading||Boolean(error);mapNotice.hidden=!loading&&!error;mapNotice.textContent=error?'当前范围地图暂不可用：'+error:'正在读取当前研究范围的地图与档案…';},country:$('#country').value,countryCodes:routeState.countryCodes,relationMode:routeState.relationMode||'external',query:new URLSearchParams(filters()).toString(),onState:({selected,mode})=>{routeState.countryCodes=selected;routeState.relationMode=mode;$('#country').value=selected.length===1?selected[0]:'';saveCurrentNavigation();},onScope:(payload,selected,focus)=>{
  if(!canvas.isConnected)return;const counts=new Map(),connections=new Map();for(const e of payload.events)for(const code of e.countries)counts.set(code,(counts.get(code)||0)+1);for(const c of payload.caseStudies||[])for(const code of c.content.countries)counts.set(code,(counts.get(code)||0)+1);
  for(const r of [...payload.coOccurrences,...(payload.confirmedRelations||[])]){const key=r.countryA+'|'+r.countryB,edge=connections.get(key)||{from:r.countryA,to:r.countryB,count:0,eventIds:[],proofs:[]};edge.count++;if(r.eventId)edge.eventIds.push(r.eventId);edge.proofs.push(r);connections.set(key,edge);}
  countryMapData={...data,countries:data.countryOptions.filter(c=>counts.has(c.code)).map(c=>({...c,count:counts.get(c.code)})),connections:[...connections.values()],events:payload.events,evidence:[]};
  canvas.innerHTML=map(countryMapData,focus);canvas.querySelectorAll('.land[data-country]').forEach(el=>el.classList.toggle('research-selected',selected.includes(el.dataset.country)));
  setupMapFlow();setupGlobe(world,countryMapData,focus,code=>countryDispose.focus?.(code));
 }});
}
document.addEventListener('click',e=>{
 if(activeTab()!=='dashboard')return;const el=e.target.closest('[data-country],[data-global],[data-connection]');if(!el)return;
 e.preventDefault();e.stopImmediatePropagation();
 if(el.hasAttribute('data-global'))return countryDispose.clear?.();
 if(el.dataset.country){if(/^[A-Z]{2}$/.test(el.dataset.country))countryDispose.focus?.(el.dataset.country);return;}
 const edge=countryMapData?.connections[Number(el.dataset.connection)];if(!edge)return;
 $('#detail-body').innerHTML='<h2>跨国关联依据</h2><p>当前研究范围内的事件与项目案例；项目商业关系不等于国家战略关系。</p>'+edge.proofs.map(r=>'<article><small>'+esc(r.confirmed?'有原文支持的项目关系 · '+(r.stage==='signed_conditional'?'附条件协议':'已记录阶段'):'地域共现 · 关系性质待核验')+'</small><h3>'+esc(r.title)+'</h3>'+r.references.map(ref=>'<blockquote>'+esc(ref.quote)+'</blockquote><button data-map-source="'+esc(ref.documentId)+'" data-body="'+esc(ref.bodyVersionId)+'" data-release="'+esc(ref.releaseId)+'">核对原文与来源 ↗</button>').join('')+'</article>').join('');enhanceReader($('#detail'));$('#detail').showModal();
},true);
document.addEventListener('click',async e=>{const b=e.target.closest('[data-map-source]');if(!b)return;b.disabled=true;const holder=b.parentElement;try{const v=await api('document/'+encodeURIComponent(b.dataset.mapSource)+'/versions/'+encodeURIComponent(b.dataset.body)+'?releaseId='+encodeURIComponent(b.dataset.release));if(!b.isConnected)return;const box=document.createElement('section');box.innerHTML=`<h3>${esc(v.data.titleZh||v.data.title)}</h3>${originalSourceLink(v.data.url)}<details><summary>查看保存的原文</summary>${articleBody(v.data.contentZh||v.data.content)}</details>`;b.replaceWith(box);}catch(error){if(b.isConnected){b.disabled=false;b.textContent='读取失败，点击重试';b.title=error.message;}}});
