async function loadSourceFunnels(){const hosts=[...document.querySelectorAll('[data-source-funnel]')];if(!hosts.length)return;try{const stats=await api('source-funnels');if(tab!=='sources')return;data.sourceFunnels=stats;for(const host of hosts)if(host.isConnected)host.innerHTML=sourceFunnel(data.sources.find(s=>s.id===host.dataset.sourceFunnel));}catch{for(const host of hosts)if(host.isConnected)host.textContent='采集分类统计暂未取得，可稍后重试。';}}
function panel(title,sub,body,extra=''){return `<section class="panel"><div class="panel-head"><div><small>${esc(sub)}</small><h2>${esc(title)}</h2></div>${extra}</div>${body}</section>`;}
function eventCard(e,compact=false){const d=doc(e.documentId);return `<article class="${compact?'row':'list-card'}"><div class="meta"><span>${esc(topicLabel(e.topic))}</span><span>${esc(formatDisplayDate(e.publishedAt||'日期待核对'))}</span></div><h3><button class="link" data-document="${e.documentId}">${esc(e.title)}</button></h3>${e.originalTitle?`<p class="original-title">${esc(e.originalTitle)}</p>`:''}${compact?'':`<p>${esc(e.summary?.slice(0,230))}</p>`}<div class="meta">${sourceTag(d?.sourceId,source(d?.sourceId))}<span>${e.evidenceIds.length} 条原文证据</span><span>${e.countries.map(c=>data.countryOptions.find(x=>x.code===c)?.name||c).join(' / ')}</span></div>${compact?'':`<div class="card-actions"><button data-document="${e.documentId}">原文与证据 ↗</button></div>`}</article>`;}
let mapMode=localStorage.getItem('ocean-map-mode')||'flat';
function map(mapData=data,selected=$('#country').value){if(mapMode!=='globe')return countryMap(mapData,world,selected);return `<div class="map-selection">3D 地球 · 拖动或方向键旋转，点击国家查看资料</div><div class="earth-tools"><select id="earth-country" aria-label="地球国家选择"><option value="">全球国家</option>${world.map(c=>`<option value="${esc(c.code)}" ${c.code===selected?'selected':''}>${esc(c.name)}</option>`).join('')}</select><button id="earth-spin" aria-pressed="false">自动旋转</button></div><canvas id="earth-canvas" tabindex="0" aria-label="可拖动旋转的3D地球；也可使用上方国家选择框"></canvas><p class="map-note">${esc(world.find(c=>c.code===selected)?.name||'全球视野')} · ${selected?(mapData.countries.find(c=>c.code===selected)?.count||0)+' 条当前国家线索':mapData.connections.length+' 组国家关联'}。点击弧线查看证据；往返亮点表示方向未确定，单向箭头仅用于原文明确的运输方向，非实时航迹。</p>`;}
function setupRadar(){const radar=$('.orbit');if(!radar)return;radar.classList.add('radar');radar.removeAttribute('aria-hidden');const job=data.collection||{};radar.innerHTML='<div class="radar-grid"></div><div class="radar-sweep"></div><i></i><i></i><i></i><span class="radar-core">◈</span><p class="radar-status">'+(job.running?'正在采集与分析':job.enabled?'定时监测已开启':'数据感知')+'<small>扫描动画示意 · 非实时信号</small></p>';}

function chart(){const t=data.timeline;if(!t.length)return '<div class="empty">当前时间范围暂无资料</div>';const max=Math.max(...t.map(x=>x.count)),points=t.map((x,i)=>({x:25+i*510/Math.max(1,t.length-1),y:130-100*x.count/max,...x}));return `<svg class="line-chart" viewBox="0 0 560 170"><path d="M25 130H535" style="stroke:var(--line)"/><path d="${points.map((p,i)=>(i?'L':'M')+p.x+','+p.y).join(' ')}"/>${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4"><title>${p.month}：${p.count} 条</title></circle><text x="${p.x}" y="${p.y-12}" text-anchor="middle">${p.count}</text><text x="${p.x}" y="157" text-anchor="middle">${p.month.slice(2)}</text>`).join('')}</svg><p class="map-note">按报道发布日期聚合。规则线索未完成跨报道事件归并；资料增长不代表产业增长。</p>`;}
function sourceCoverage(s){
 const n=data.documents.filter(d=>d.sourceId===s.id).length,series=(data.series||[]).filter(x=>x.sourceId===s.id),points=series.reduce((sum,x)=>sum+x.rows.length,0);
 const explanation=points?`这个渠道提供统计数据。${points} 条统计数据表示 ${points} 条指标数值记录，不是文章篇数；每条记录对应某个指标在一个统计期的数值。${n?'该渠道也收录了文章。':'“暂无文章”表示此渠道当前未收录文章，不影响统计数据使用。'}`:s.method==='rss'?'RSS 是文章订阅渠道，用于发现来源新发布的文章；“篇”表示本站已收录的文章数量。':'这是资料来源；“篇”表示本站已收录的文章数量，暂无文章不代表原网站没有发布内容。';
 const url=s.url||series[0]?.sourceUrl,linked=/^https?:\/\//i.test(url||''),tipId='coverage-tip-'+s.id;
 const label=`<b>${esc(s.name)}</b><span>文章 / 文档 ${n} 篇${points?' · 统计数据 '+points+' 条':''}</span><span>${esc(s.level)} · ${esc(s.method.toUpperCase())}</span>${linked?'<span aria-hidden="true">↗</span>':''}`;
 return `<div class="row source-coverage"><${linked?'a':'span'} class="meta coverage-link" ${linked?`href="${esc(url)}" target="_blank" rel="noopener noreferrer"`:'tabindex="0"'} aria-describedby="${esc(tipId)}">${label}</${linked?'a':'span'}><div class="coverage-tip" id="${esc(tipId)}" role="tooltip">${esc(explanation)}${points?' RSS 则是文章订阅渠道，文章篇数与统计数据分别计数。':''}${linked?'<br>点击来源信息，在新标签页打开原始数据源。':''}</div><div class="bar-track"><i style="width:${100*n/Math.max(1,data.documents.length)}%"></i></div></div>`;
}
let disposeDashboardCharts=()=>{};
async function setupDashboardCharts(){disposeDashboardCharts();disposeDashboardCharts=()=>{};const host=$('#dashboard-distribution');if(!host)return;host.innerHTML='<p class="meta">正在准备资料分布图表…</p>';try{const {mountDashboardCharts}=await import('./quant/app.js');if(host.isConnected)disposeDashboardCharts=mountDashboardCharts(host,'?'+new URLSearchParams(filters()));}catch(e){if(host.isConnected)host.textContent='资料分布暂未加载，请刷新重试。';}}
function dashboard(){const m=data.metrics;return `<div class="metrics">${[['文章 / 文档',m.documents,metricNotes.articles],['事件与报道线索',m.events,metricNotes.events],['已识别实体',m.entities,metricNotes.entities],['实体关系',m.relations,metricNotes.relations]].map(([t,n,d])=>`<div class="metric" title="${esc(d)}" tabindex="0"><span>${t} ⓘ</span><strong>${n}</strong><small>悬停查看计数口径与核对位置</small></div>`).join('')}</div><div class="dashboard-map-row">${panel('全球情报分布','GLOBAL LANDSCAPE','<p class="meta">基于已收录情报展示地域分布与关联线索。</p>'+map(),`<div class="map-switch" role="group" aria-label="地图显示方式"><button data-map-mode="flat" aria-pressed="${mapMode==='flat'}">平面图</button><button data-map-mode="globe" aria-pressed="${mapMode==='globe'}">3D 地球</button><button data-global>返回全球 ↶</button></div>`)}${panel('最新报道与变化线索','DISCOVER WHAT MATTERS','<div class="dashboard-latest">'+(data.events.slice().sort((a,b)=>(b.publishedAt||'').localeCompare(a.publishedAt||'')).slice(0,4).map(e=>eventCard(e,true)).join('')||'<p class="empty">当前筛选范围暂无报道线索。</p>')+'</div><a class="dashboard-latest-more" href="#monitor?view=events">查看全部产业动态 →</a>')}</div>${panel('变化信号与研判','CHANGE SIGNALS / EVIDENCE FIRST','<div id="change-signals">'+renderChangeSignals(data,signalDays,signalTheme)+'</div>')}${panel('国家关联网络','COUNTRY CONNECTIONS',networkView(data))}<section id="dashboard-distribution" class="panel"></section>`;}
const pages={events:1,library:1},sizes={events:10,library:10};let libraryQuery='';
function pageList(rows,kind,card){
 const total=rows.length,last=Math.max(1,Math.ceil(total/sizes[kind]));pages[kind]=Math.min(pages[kind],last);const page=pages[kind];
 const pager=`<div class="pagination"><span>共 ${total} 条 · 第 ${page} / ${last} 页</span><label>每页 <select data-size="${kind}">${[10,20,50].map(n=>`<option ${sizes[kind]===n?'selected':''}>${n}</option>`).join('')}</select> 条</label><button data-page="${kind}" data-next="${page-1}" ${page===1?'disabled':''}>上一页</button><button data-page="${kind}" data-next="${page+1}" ${page===last?'disabled':''}>下一页</button></div>`;
 return pager+`<div class="page-results">${rows.slice((page-1)*sizes[kind],page*sizes[kind]).map(card).join('')||'<p class="empty">没有符合条件的资料</p>'}</div>`+(total>sizes[kind]?pager:'');
}
function libraryResults(){return pageList(data.documents.filter(d=>(d.title+' '+d.titleZh+' '+d.summaryZh).toLowerCase().includes(libraryQuery.toLowerCase())).slice().sort((a,b)=>(b.publishedAt||'').localeCompare(a.publishedAt||'')),'library',d=>articles([d]));}
function library(){return `<div class="searchbar"><input id="search" value="${esc(libraryQuery)}" placeholder="搜索标题、实体或摘要" aria-label="搜索资料"><button id="search-btn">搜索</button></div><div id="articles-list">${libraryResults()}</div>`;}
const extractionJobs=new Map();
function extractionFeedback(id){const job=extractionJobs.get(id);return job?`<div class="extract-feedback ${job.error?'extract-error':''}" role="status">${esc(job.message)}${job.result?` <button data-extract-result="${id}">查看本次结果 ↗</button>`:''}</div>`:'';}
function showExtractionResult(r){$('#detail-body').innerHTML=`<h2>本篇实体关系提取结果</h2><h3>${esc(r.title)}</h3><p>${esc(r.method)}完成：识别 ${r.entities} 个实体、${r.relations} 条关系；新增入库 ${r.addedEntities} 个实体、${r.addedRelations} 条关系。重复记录合并，人工排除结果保留。</p><div class="chips">${r.result.entities.map(e=>`<span class="badge">${esc(e.name)} · ${esc(e.type)}</span>`).join('')}</div>${r.result.relations.map(rel=>`<div class="row"><strong>${esc(rel.from)} → ${esc(rel.type)} → ${esc(rel.to)}</strong><details><summary>原文依据</summary>${rel.evidence.map(q=>`<blockquote>${esc(q)}</blockquote>`).join('')}</details></div>`).join('')||'<p class="notice">本次未找到具有明确原文依据的关系。不根据实体共同出现自动推断合作；既有资料和关系保留。</p>'}<p><button data-document="${r.documentId}">查看完整原文与证据</button> <a href="#graph" id="extract-open-graph">前往产业关联图谱 ↗</a></p>`;if(!$('#detail').open)$('#detail').showModal();$('#extract-open-graph').onclick=()=>$('#detail').close();}
async function runExtraction(button){const id=button.dataset.extract;if(extractionJobs.get(id)?.pending)return;const job={pending:true,message:'正在分析文章正文并匹配原文证据，请稍候…'};extractionJobs.set(id,job);button.disabled=true;button.textContent='正在提取…';button.setAttribute('aria-busy','true');const card=button.closest('.maintenance')||button.closest('.list-card');card.querySelector('.extract-feedback')?.remove();card.insertAdjacentHTML('beforeend',extractionFeedback(id));
 try{const r=await api('extract',{id});job.result=r;job.message=`提取完成：${r.entities} 个实体、${r.relations} 条关系（新增 ${r.addedRelations} 条关系）。`;job.pending=false;await load();showExtractionResult(r);}catch(err){job.error=true;job.message=err.message;job.pending=false;if(button.isConnected){card.querySelector('.extract-feedback')?.remove();card.insertAdjacentHTML('beforeend',extractionFeedback(id));}}finally{job.pending=false;if(button.isConnected){button.disabled=false;button.textContent=job.error?'重试提取':'提取实体关系';button.removeAttribute('aria-busy');}}
}
function articles(ds){return ds.map(d=>`<article class="list-card"><div class="meta">${sourceTag(d.sourceId,source(d.sourceId))}<span>${esc(formatDisplayDate(d.publishedAt||'发布时间待核对'))}</span><span>${esc(topicLabel(d.topic))}</span><span>${esc(d.translationType?.replace('，译文待核对',''))}</span></div><h3>${esc(d.titleZh||d.title)}</h3>${d.titleZh&&d.titleZh!==d.title?`<p class="original-title">${esc(d.title)}</p>`:''}<p>${esc(d.summaryZh?.slice(0,220))}</p><div class="card-actions"><button data-document="${d.id}">查看正文与证据 ↗</button><a href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">原始文章 ↗</a><a class="meta" href="${esc(d.url)}" target="_blank" rel="noopener noreferrer" title="按采集记录显示来源；不推断转载文章的首发媒体">正文来源：${esc(d.originalPublisher||data.sources.find(s=>s.id===d.sourceId)?.name||'原文未标明')}${d.manual?' · 人工录入':''}</a></div>${extractionFeedback(d.id)}</article>`).join('')||'<div class="empty">没有符合条件的资料</div>';}
let quantView,quantHost,quantAssets;let loadVersion=0;
function analysis(){return '<section id="quant-native" aria-label="行业数据洞察"><p role="status">正在准备量化图表…</p></section>';}
async function setupQuant(){const host=$('#quant-native');if(!host)return;if(quantHost===host&&quantView){quantView.update('?'+new URLSearchParams(filters()));return;}quantView?.dispose();quantView=null;quantHost=host;try{quantAssets ||= Promise.all([import('./quant/app.js'),fetch('quant/index.html').then(r=>{if(!r.ok)throw Error('图表模板加载失败');return r.text();}),fetch('quant/style.css').then(r=>r.text()),window.echarts?Promise.resolve():new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='quant/echarts.js';script.onload=resolve;script.onerror=()=>reject(Error('图表引擎加载失败'));document.head.append(script);})]).catch(e=>{quantAssets=null;throw e;});const [module,html,css]=await quantAssets;if(!host.isConnected||quantHost!==host)return;const root=host.shadowRoot||host.attachShadow({mode:'open'});const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelector('.hero')?.remove();const style=css.replaceAll(':root',':host').replaceAll('body.embedded', '.quant-shell').replaceAll('body', '.quant-shell').replaceAll('[data-theme="dark"]', ':host([data-theme="dark"])').replaceAll(':host:host',':host');root.innerHTML='<style>'+style+' :host{display:block;color:var(--ink);font:14px/1.7 Segoe UI,Microsoft YaHei,sans-serif}main{margin:0;padding:0}#content[aria-busy="true"]{opacity:.65;pointer-events:none}#content{transition:opacity .18s ease}header{height:52px}.quant-shell{background:transparent} @media(prefers-reduced-motion:reduce){#content{transition:none}}</style><div class="quant-shell">'+doc.querySelector('main').outerHTML+'</div>';host.replaceChildren();quantView=module.mountQuant(root,'?'+new URLSearchParams(filters()));}catch(e){if(host.isConnected)host.innerHTML='<p role="status">'+esc(e.message)+'</p><button id="retry-quant">重新加载图表</button>';}}

function graph(){return panel('产业关联图谱','INDUSTRY CONNECTIONS',relationshipView(data));}
function researchQA(){return `<div class="grid">${panel('从一个问题开始研究','RESEARCH WORKBENCH',`<p class="meta">${modelReady?'关键词与语义检索，生成带来源的研究草稿。':'当前为证据检索模式：不调用付费模型，不生成综合形势判断。'}</p><details class="search-help"><summary>这些证据如何匹配？</summary><p class="meta">先强制匹配已识别的主体与国家（例如“中国海油 巴西”必须同时出现中国海油或CNOOC，以及巴西或Brazil）；空格分隔的简短关键词也按同时满足处理。随后融合关键词与可用语义向量，最多返回8项证据。EIA及Transocean统计按指标主题和国家匹配，并保留统计期、单位、逐期数值及来源。尚未覆盖所有主体别名，也不自动理解“最近几个月”，请使用顶部时间筛选。当前结果正文为已保存摘要，不一定是命中位置；检索到文章不代表其支持全部问题。</p></details><textarea id="question" aria-label="研究问题" placeholder="例如：Northern Lights 最近有哪些进展，依据是什么？"></textarea><div class="chips">${['Northern Lights 封存','海上风电','中国海油 巴西','EIA美国海上原油产量变化'].map(q=>`<button data-question="${q}">${q} ↗</button>`).join('')}</div><button id="ask" class="primary">${modelReady?'生成研究草稿':'检索相关证据'} →</button><div id="answer" class="answer" style="margin-top:24px"></div><div id="research-actions"></div>`)}${panel('研究证据','EVIDENCE FIRST','<div id="references" class="empty">检索后，原文、来源、日期<br>和证据片段会呈现在这里。</div>')}</div><section class="panel" style="margin-top:20px"><h2>研究记录</h2><div id="history"></div></section>`;}
function research(){return strategyShell(researchQA());}
function sourceFunnel(s){const f=data.sourceFunnels?.[s.id];if(!f)return s.id.startsWith('mp2rss_')?'<p class="meta">当前分类统计暂未取得，请稍后刷新。</p>':'';return '<div class="source-funnel" style="display:flex;flex-wrap:wrap;gap:10px;margin:12px 0">'+[['文章总数',f.collected],['已纳入',f.included],['已排除',f.excluded],['待筛选',f.pending]].map(([n,v])=>'<span style="padding:7px 10px;border:1px solid #42647b;border-radius:8px">'+n+' <b>'+v+'</b></span>').join('')+'</div><p class="meta">文章总数 = 已纳入 + 已排除 + 待筛选（本订阅原文链接去重）。同步至工作库 '+f.bridge.delivered+' / '+f.bridge.eligible+' 篇；同步进度不改变分类数量。统计时间 '+esc(f.observedAt)+'</p>';}

function sources(){const job=data.collection||{},processing=data.processing||{};return `<section class="panel" style="margin-bottom:20px"><h2>自动采集与分析</h2><p>采集新文章 → 自动提取 → 关联原文证据 → 翻译与检索准备 → 更新各栏目</p><p class="meta">已入库自动结构化 ${processing.completed||0} 篇 · 等待自动处理 ${processing.pending||0} 篇 · 后续重试 ${processing.retry||0} 篇。无变化的正文不会重复调用模型；失败保留已有资料与人工校准。</p><p>${job.enabled?'已开启 · 每6小时检查来源':'尚未开启'} · ${job.running?'正在采集、自动分析与更新':'等待下次运行'}</p><p class="meta">上次完成：${esc(formatDisplayDate(job.lastRun||'尚无完成记录'))}<br>下次运行：${esc(formatDisplayDate(job.nextRun||'未安排'))}<br>任务结果：${esc(job.result||'等待首次运行')}</p><button id="collect-now" ${job.running?'disabled':''}>立即检查更新</button><p class="meta">通过RSS与官方列表增量发现新文章，指定文章作为补充来源。自动分析、翻译与向量处理失败会记录并在后续任务重试；新资料成功入库后刷新页面即可看到。</p></section><div class="source-cards">${data.sources.map(s=>panel(s.name,s.level+' / '+s.method.toUpperCase(),`<div data-source-funnel="${esc(s.id)}">${sourceFunnel(s)}</div><p><span class="status-dot"></span>${s.status==='ready'?'采集就绪':s.status==='empty'?'本轮暂无新增':esc(s.status)} · ${countHelp('智库文档 '+data.documents.filter(d=>d.sourceId===s.id).length+' 篇',metricNotes.articles+' 本卡按该渠道计数。')} · ${countHelp('统计数据 '+(data.series||[]).filter(x=>x.sourceId===s.id).reduce((n,x)=>n+x.rows.length,0)+' 条',metricNotes.points+' 本卡按该渠道计数。')} · ${countHelp('文章提取指标 '+data.observations.filter(o=>data.documents.some(d=>d.id===o.documentId&&d.sourceId===s.id)).length+' 条',metricNotes.observations)}</p><p>${esc(s.scope)}</p>${s.id==='iea'?'<p>官方工作簿：'+(data.officialSummary?.accepted||0)+' 条纳入 · '+(data.officialSummary?.projects||0)+' 条项目／阶段登记 · '+(data.officialSummary?.candidates||0)+' 条候选。数据复用于行业数据洞察，逐条保留工作表、单元格与版本。</p>':''}<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.url)} ↗</a><p>获取方式：${s.method==='dataset-and-news'?'登录授权工作簿下载 + Mp2RSS 资讯':s.method==='manual'?'人工录入链接与原文片段':s.method==='rss'?'RSS 发现 + 正文提取':s.method==='api'?(s.id.startsWith('mp2rss_')?'Mp2RSS 第三方 API（原文平台另列）':'官方API'):s.method==='web-pdf'?'官方网页与PDF报告索引':s.method==='table'?'官方月度表格解析':'官方列表／指定文章 + 正文提取'}<br>更新方式：${s.id==='iea'?'数据集每7天检查版本；资讯每30分钟采集':s.id.startsWith('mp2rss_')?'每30分钟采集；主题通过后自动投递分析':s.method==='manual'?'人工录入':job.eiaExternal&&s.id.startsWith('eia')?'独立每日采集任务，与资讯任务互斥':job.enabled?'每6小时检查；新资料增量处理':'人工触发'}<br>最后检查：${esc(formatDisplayDate(s.checkedAt,'本轮采集'))}</p>`)).join('')}</div><div class="notice" style="margin-top:20px">已接入官方、行业资讯与指标来源。来源登记与采集脚本可扩展；本轮采集窗口 ${data.window.since} 至 ${data.window.until}，不代表期间全量覆盖。采集任务状态见上方；新闻与指标按各自发布频率更新，定时检查不代表每轮都有新数据。</div>${panel('采集异常与缺口','COLLECTION HEALTH',data.errors.length?data.errors.slice(-12).map(e=>`<div class="row"><p>${esc(e.sourceId)} · ${esc(e.error)}</p><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">查看来源 ↗</a></div>`).join(''):'<p class="meta">本轮没有记录到采集异常。</p>')}`;}
