const calibrationRecords=new Map(),calibrationEvidence=new Map();
function maintenance(d){for(const e of d.evidence||[])calibrationEvidence.set(e.id,e);let rows='';for(const [kind,label] of [['events','事件'],['relations','关系'],['observations','指标']])for(const r of d[kind]||[]){calibrationRecords.set(kind+':'+r.id,r);const title=r.title||r.name||(entity(r.from)?.nameZh||entity(r.from)?.name||'主体')+' → '+r.type+' → '+(entity(r.to)?.nameZh||entity(r.to)?.name||'对象');rows+=`<div class="row"><span>${label}：${esc(title)}</span><p class="meta">${r.status==='rejected'?'已人工排除':r.status==='verified'?'已人工确认':'系统正常展示'}${r.reviewNote?' · '+esc(r.reviewNote):''}</p><button data-review="${kind}:${r.id}">校准此项</button>${r.reviewHistory?.length?`<details><summary>校准记录</summary>${r.reviewHistory.map(h=>`<p class="meta">${esc(h.at)} · ${h.status==='rejected'?'排除':'确认支持'} · ${esc(h.note)}</p>`).join('')}</details>`:''}</div>`;}return `<details class="maintenance"><summary>资料维护</summary><p class="meta">发现内容不准确时可进入人工校准。操作仅影响所选条目，并保留来源与校准说明。</p>${rows||'<p>该资料暂无可校准的结构化条目。</p>'}<p class="meta">新文章会自动分析。仅在需要补充或重试时重新提取。</p><button data-extract="${d.id}" ${extractionJobs.get(d.id)?.pending?'disabled aria-busy="true"':''}>${extractionJobs.get(d.id)?.pending?'正在提取…':'重新提取实体关系'}</button>${extractionFeedback(d.id)}</details>`;}
async function openDoc(id){const d=await api('document/'+id);$('#detail-body').innerHTML=`<div class="meta">${esc(source(d.sourceId))} · ${esc(formatDisplayDate(d.publishedAt||'日期待核对'))}</div><h2>${esc(d.titleZh||d.title)}</h2><p class="meta">原始标题：${esc(d.title)}<br>正文来源：${esc(d.originalPublisher||data.sources.find(s=>s.id===d.sourceId)?.name||'原文未标明')}<br>采集时间：${esc(formatDisplayDate(d.collectedAt))}<br>${esc(d.translationType?.replace('，译文待核对',''))}${d.titleTranslation?`<br>标题：${esc(d.titleTranslation)}`:''}</p>${originalSourceLink(d.url)}<h3 style="margin-top:24px">证据摘录</h3><p class="meta">以下为与资讯关联的原文片段。当前部分片段使用固定长度截取，可能截断句词或包含相关文章；请结合完整正文与原始网页核对。</p>${d.evidence.map(e=>`<div class="evidence"><div class="translation-label">原文摘录</div>${esc(e.quote)}${e.quoteZh?`<div class="translation-label">中文译文 · AI翻译</div><p>${esc(e.quoteZh)}</p>`:''}</div>`).join('')}<details><summary>展开完整正文 · 原文／中文译文</summary><p class="meta">已去除网页标签并尝试提取正文、整理空白；不是翻译或改写，仍可能残留推荐内容。清洗前的网页快照在采集端保存，本窗口展示提取文本。</p><div class="bilingual-body"><section><h3>原文正文</h3>${articleBody(d.content)}</section><section><h3>中文正文译文</h3>${articleBody(d.contentZh||(d.language==='zh'?d.content:'译文尚未完成，后续任务将补充。'))}<p class="meta">AI译文辅助阅读，事实以原文为准。</p></section></div></details>${xEvidenceView(d)}${maintenance(d)}`;enhanceReader($('#detail'));$('#detail').showModal();}
async function review(kind,id){const r=calibrationRecords.get(kind+':'+id)||data[kind].find(r=>r.id===id);$('#detail-body').innerHTML=`<h2>内容校准</h2><p>请先阅读原文，确认对象、关系方向、数字单位和统计期间。</p><p class="meta">资讯默认正常展示。如果发现所选条目有误，可记录原因并排除；确认原文支持可保留或恢复展示。操作不会连带更改其他条目，原文和操作记录保留。</p>${r.evidenceIds.map(eid=>(calibrationEvidence.get(eid)||data.evidence.find(e=>e.id===eid))).filter(Boolean).map(e=>`<div class="evidence">${esc(e.quote)}</div>`).join('')}<a href="${esc(doc(r.documentId)?.url)}" target="_blank" rel="noopener noreferrer">打开原文 ↗</a><textarea id="review-note" placeholder="填写校准说明或排除原因（必填）"></textarea><div class="chips"><button data-save-review="verified" data-kind="${kind}" data-id="${id}">确认支持／恢复展示</button><button data-save-review="rejected" data-kind="${kind}" data-id="${id}">排除此项</button></div>`;$('#detail').showModal();}
