document.addEventListener('change',e=>{if(e.target.dataset.size){sizes[e.target.dataset.size]=Number(e.target.value);pages[e.target.dataset.size]=1;render();}});
document.addEventListener('click',async e=>{const signalButton=e.target.closest('[data-signal-days]');if(signalButton){signalDays=Number(signalButton.dataset.signalDays);$('#change-signals').innerHTML=renderChangeSignals(data,signalDays,signalTheme);return;}const themeButton=e.target.closest('[data-signal-theme]');if(themeButton){signalTheme=themeButton.dataset.signalTheme;$('#change-signals').innerHTML=renderChangeSignals(data,signalDays,signalTheme);$('#change-signals').querySelectorAll('[data-signal-theme]').forEach(b=>{if(b.dataset.signalTheme===signalTheme)b.focus({preventScroll:true});});return;}const proofButton=e.target.closest('[data-signal-proof]');if(proofButton){$('#detail-body').innerHTML=renderSignalEvidence(data,signalDays,proofButton.dataset.signalProof);$('#detail').showModal();return;}if(e.target.dataset.mapMode){mapMode=e.target.dataset.mapMode;localStorage.setItem('ocean-map-mode',mapMode);render();return;}if(e.target.id==='retry-quant'){setupQuant();return;}if(e.target.dataset.page){pages[e.target.dataset.page]=Number(e.target.dataset.next);render();$('#content').scrollIntoView({block:'start'});return;}if(e.target.dataset.seriesResearch){pendingQuestion=e.target.dataset.seriesResearch;if(location.hash==='#research')render();else location.hash='research';return;}if(e.target.dataset.seriesRef){const r=lastResearch.references.find(r=>r.number===Number(e.target.dataset.seriesRef));$('#detail-body').innerHTML=`<h2>${esc(r.titleZh)}</h2><p>${esc(r.note)}</p><p class="meta">统计期：${esc(r.periodRange)}；读取时间：${esc(formatDisplayDate(r.checkedAt))}（不是发布日期）</p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">官方原始数据 ↗</a><div class="table-wrap"><table><tr><th>统计期</th><th>数值</th><th>单位</th><th>原始来源</th></tr>${r.rows.map(v=>`<tr><td>${esc(v.period)}</td><td>${v.value}</td><td>${esc(r.unit)}</td><td><a href="${esc(v.sourceUrl||r.url)}" target="_blank" rel="noopener noreferrer">官方来源 ↗</a>${v.publishedAt?`<p class="meta">发布：${esc(formatDisplayDate(v.publishedAt))}</p>`:''}</td></tr>`).join('')}</table></div>`;$('#detail').showModal();return;}const el=e.target.closest('[data-document],[data-country],[data-connection],[data-global],[data-review],[data-save-review],[data-question],[data-history]');try{if(el?.dataset.document)await openDoc(el.dataset.document);if(el?.dataset.country){const code=el.dataset.country;if(![...$('#country').options].some(o=>o.value===code)){const selected=world.find(c=>c.code===code);if(selected)$('#country').add(new Option(selected.name,code));}$('#country').value=code;pages.events=pages.library=1;saveCurrentNavigation();await load();}if(el?.hasAttribute('data-global')){$('#country').value='';saveCurrentNavigation();await load();}if(el?.dataset.connection!==undefined){const r=data.connections[Number(el.dataset.connection)];const direction=connectionDirection(r,data);$('#detail-body').innerHTML=(direction?'<h2>原文中的运输方向</h2><p>箭头仅表示下列原文明确的起终点；不代表实时运输或所有共现事件的方向。</p>'+direction.evidence.map(p=>'<blockquote>'+esc(p.quote)+'</blockquote>').join(''):'<h2>地域共现的原文依据</h2><p>方向未确定，往返脉冲仅用于提示关联，不代表双向合作或实际运输。</p>')+data.events.filter(x=>r.eventIds.includes(x.id)).map(x=>eventCard(x)).join('');$('#detail').showModal();}if(el?.dataset.review){const [kind,id]=el.dataset.review.split(':');await review(kind,id);}if(el?.dataset.saveReview){await api('review',{kind:el.dataset.kind,id:el.dataset.id,status:el.dataset.saveReview,note:$('#review-note').value});$('#detail').close();await load();}if(el?.dataset.question)$('#question').value=el.dataset.question;if(el?.dataset.history){const r=window.researchHistory.find(x=>x.id===el.dataset.history);$('#detail-body').innerHTML=`<h2>${esc(r.question)}</h2><div class="answer markdown">${markdown(r.answer)}</div>${r.references.map(ref=>`<div class="row"><a href="${esc(ref.url)}" target="_blank" rel="noopener noreferrer">[${ref.number}] ${esc(ref.titleZh)}</a><p>${esc(formatDisplayDate(ref.periodRange||ref.publishedAt||'发布日期未提供'))}</p></div>`).join('')}`;$('#detail').showModal();}if(e.target.closest('[data-extract]'))await runExtraction(e.target.closest('[data-extract]'));if(e.target.dataset.extractResult)showExtractionResult(extractionJobs.get(e.target.dataset.extractResult).result);if(e.target.closest('#add-event'))await openManualIntake();if(e.target.id==='collect-now'){await api('collection',{});e.target.disabled=true;$('#notice').textContent='采集任务已启动，稍后刷新可查看进度。';}if(e.target.id==='ask')await ask();if(e.target.id==='search-btn'){libraryQuery=$('#search').value.trim();pages.library=1;$('#articles-list').innerHTML=libraryResults();}if(e.target.id==='export-csv'){const rows=[['指标','对象','原值','单位','性质','期间','原文地址'],...data.observations.map(m=>[m.name,m.subject,m.rawValue,m.unit,m.nature,m.period,doc(m.documentId)?.url])];download('原文指标观察.csv','\ufeff'+rows.map(r=>r.map(c=>'"'+String(c??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');}if(e.target.id==='export-brief'){const text=lastResearch.question+'\n研究结果 · 附原始来源\n'+formatDisplayDate(lastResearch.createdAt)+'（北京时间）'+'\n\n'+lastResearch.answer+'\n\n参考来源\n'+lastResearch.references.map(r=>`[${r.number}] ${r.titleZh}\n${formatDisplayDate(r.publishedAt)} · ${source(r.sourceId)}\n${r.url}`).join('\n\n');$('#detail-body').innerHTML='<h2>TXT 简报预览</h2><pre>'+esc(text)+'</pre><button id="download-brief">下载 TXT</button>';$('#detail').showModal();$('#download-brief').onclick=()=>download('海洋能源证据简报.txt',text);}}catch(err){$('#notice').textContent=err.message;}});
document.querySelector('#nav').addEventListener('click',async e=>{
 const a=e.target.closest('a[data-tab]');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();
 navigationState.shared={};navigationState.local={};for(const key of Object.keys(sessionStorage))if(key.startsWith('object-browser'))sessionStorage.removeItem(key);sessionStorage.removeItem('selected-period-report');saveNavigation(sessionStorage,navigationState);
 const next='#'+a.dataset.tab;if(location.hash===next){restoreNavigation();await load({navigation:true});window.scrollTo({top:0,behavior:'instant'});}else location.hash=next;
});
$('#close-detail').onclick=()=>$('#detail').close();$('#theme').onclick=()=>{document.body.classList.toggle('light');localStorage.setItem('ocean-theme',document.body.classList.contains('light')?'light':'dark');};if(localStorage.getItem('ocean-theme')==='light')document.body.classList.add('light');$('#logout').onclick=async()=>{strategyDispose();strategyDispose=()=>{};clearStrategyDraft();invalidateSensingCache();clearCountryCache();await api('logout',{});location.reload();};$('#login-form').onsubmit=async e=>{e.preventDefault();try{await api('login',{password:$('#password').value});$('#password').value='';$('#login').hidden=true;await load();}catch(err){$('#login-error').textContent=err.message;}};for(const id of ['topic','country','source','from','to'])$('#'+id).onchange=()=>{pages.events=pages.library=1;saveCurrentNavigation();load();};$('#reset').onclick=()=>{if(activeTab()==='dashboard'){routeState.countryCodes=[];routeState.relationMode='external';}pages.events=pages.library=1;libraryQuery='';for(const id of ['topic','country','source','from','to'])$('#'+id).value='';saveCurrentNavigation();load();};window.onhashchange=async()=>{saveCurrentNavigation(false);restoreNavigation();if(data||$('#login').hidden){await load({navigation:true});window.scrollTo({top:0,behavior:'instant'});}};document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.map-node,.land[data-country],.map-link')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
try{const [dictionary,session]=await Promise.all([fetch('world.json').then(r=>r.json()),api('session')]);world=normalizeWorld(dictionary);restoreNavigation();modelReady=session.modelReady;if(session.authenticated)await load();else $('#login').hidden=false;}catch(e){$('#notice').textContent=e.message;}

let intakeOpening=false;
async function openManualIntake(){
 if(intakeOpening)return;intakeOpening=true;
 const dialog=$('#detail'),host=$('#detail-body');host.innerHTML='<h2>补充资料</h2><p role="status">正在准备录入表单…</p>';dialog.showModal();
 try{const options=data?.topics?.length&&data?.countryOptions?.length?data:await api('intake-options');if(!dialog.open)return;
 host.innerHTML=eventForm(options);setupFileIntake($('#event-form'),api);
 $('#event-form').onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('button[type=submit]');button.disabled=true;try{await api('events',Object.fromEntries(new FormData(ev.target)));invalidateSensingCache();dialog.close();await load();$('#notice').textContent='资料已保存，渠道标记为人工上传，原始链接与证据已保留。';}catch(err){$('#event-error').textContent=err.message;}finally{button.disabled=false;}};
 }catch(err){host.innerHTML='<h2>暂时无法准备表单</h2><p role="alert">'+esc(err.message)+'</p><button id="retry-manual-intake">重试</button>';host.querySelector('button').onclick=()=>openManualIntake();}finally{intakeOpening=false;}
}

document.addEventListener("open-manual-intake",()=>openManualIntake().catch(err=>{$("#notice").textContent=err.message;}));

document.addEventListener('strategy-case-answer',e=>{const r=e.detail;if(r?.caseId&&r.id&&typeof r.answer==='string'&&Array.isArray(r.references)){showResearchAnswer(r);$('#answer').insertAdjacentHTML('afterbegin','<p class="notice">'+esc(r.mode)+'</p>');}});
